import Foundation

enum LeisureGuides {
    private static let libraries = DirectorySource(name: "BVÖ · Bibliotheksadressen", url: "https://www.bvoe.at/oeffentliche-bibliotheken/bibliotheksadressen")
    private static let sport = DirectorySource(name: "ASKÖ · Vereinssuche", url: "https://www.askoe.at/verband-vereine/vereine")
    private static let museums = DirectorySource(name: "Naturhistorisches Museum Wien · Information", url: "https://nhm-wien.ac.at/information")
    private static let culturePass = DirectorySource(name: "Hunger auf Kunst und Kultur · Kulturpass", url: "https://www.hungeraufkunstundkultur.at/")
    private static let familyPass = DirectorySource(name: "oesterreich.gv.at · Familienförderungen der Länder", url: "https://www.oesterreich.gv.at/de/themen/familie_und_partnerschaft/finanzielle-unterstuetzungen/6/Seite.080750")
    private static let bathing = DirectorySource(name: "AGES · Badegewässer Monitoring", url: "https://www.ages.at/umwelt/wasser/badegewaesser-monitoring")
    private static let parks = DirectorySource(name: "Nationalparks Austria · Natur erleben", url: "https://www.nationalparksaustria.at/de/natur-erleben.html")
    private static let parkRules = DirectorySource(name: "Nationalparks Austria · Bleib fair", url: "https://www.nationalparksaustria.at/de/bleib-fair.html")
    private static let hiking = DirectorySource(name: "Alpenverein · Sicher Bergwandern", url: "https://www.alpenverein.at/gebirgsverein/service/sicheramberg/bergwandern/index.php")

    static func guide(for topicID: String) -> DirectoryGuide? {
        guard topicID == "leisure" else { return nil }
        return DirectoryGuide(
            cardSummary: .init(ukrainian: "Куди піти, як знайти заняття та перевірити витрати", german: "Ausflüge und Angebote finden, Kosten und Bedingungen prüfen"),
            introduction: .init(ukrainian: "Оберіть заняття, знайдіть місце у своїй землі та перевірте актуальні умови безпосередньо перед відвідуванням.", german: "Angebot auswählen, Ort im eigenen Bundesland finden und aktuelle Bedingungen vor dem Besuch prüfen."),
            sections: [
                .init("library", "books.vertical", "Бібліотека поруч", "Bibliothek in der Nähe", "У каталозі Бібліотечної асоціації Австрії знайдіть бібліотеку за землею чи громадою та відкрийте її сторінку. Там перевірте години роботи, як отримати читацьку картку, плату за користування, термін позики й штрафи за прострочення. Для дитячих заходів або мовних зустрічей дивіться календар саме цієї бібліотеки: запис може бути окремим.", "Im Verzeichnis des Büchereiverbands eine Bibliothek nach Bundesland oder Gemeinde finden und deren Seite öffnen. Öffnungszeiten, Anmeldung, Ausweisgebühr, Leihfrist und Säumnisgebühren dort prüfen. Für Kinderveranstaltungen oder Sprachgruppen den Kalender dieser Bibliothek ansehen; eine eigene Anmeldung kann nötig sein.", source: libraries),
                .init("sport", "sportscourt", "Знайти спортивне заняття", "Sportangebot finden", "Пошук ASKÖ дозволяє обрати землю, район і вид спорту та побачити клуби поблизу. Зв’яжіться з обраним клубом: запитайте про вільні місця, вікову групу, пробне заняття, мову тренування, внесок і спорядження. Перед вступом з’ясуйте, чи оплата разова або річна та як припинити членство. Пошук охоплює клуби ASKÖ, а не всі пропозиції Австрії.", "Die ASKÖ-Suche filtert Vereine nach Bundesland, Bezirk und Sportart. Beim gewählten Verein freie Plätze, Altersgruppe, Schnuppertraining, Trainingssprache, Beitrag und Ausrüstung erfragen. Vor dem Beitritt klären, ob einmalig oder jährlich gezahlt wird und wie die Mitgliedschaft endet. Die Suche umfasst ASKÖ-Vereine, nicht alle Angebote Österreichs.", source: sport),
                .init("museum", "building.columns", "Музеї: квитки та вік", "Museen: Tickets und Alter", "Для музею спочатку відкрийте офіційні ціни, години й умови бронювання на дату візиту. Наприклад, у Віденському музеї природознавства вхід для осіб до 19 років безплатний; спеціальні програми можуть мати окрему ціну. Дорослий квиток, сімейні тарифи й часові слоти перевіряйте для кожного музею окремо. Візьміть документ, який підтверджує вік дитини.", "Für den Museumsbesuch zuerst offizielle Preise, Öffnungszeiten und Reservierung für das Besuchsdatum prüfen. Im Naturhistorischen Museum Wien ist etwa der Eintritt für Personen unter 19 kostenlos; Sonderprogramme können extra kosten. Erwachsenenticket, Familientarife und Zeitfenster für jedes Museum einzeln prüfen. Einen Altersnachweis für das Kind mitnehmen.", source: museums),
                .init("culture-pass", "theatermasks", "Kulturpass при низькому доході", "Kulturpass bei geringem Einkommen", "На сайті «Hunger auf Kunst und Kultur» виберіть свою землю: там указані умови отримання Kulturpass, пункти видачі й заклади-партнери. Перевірте потрібні документи та строк дії, а перед подією — чи бере участь саме цей організатор і чи потрібне бронювання. Картка стосується культурного входу в межах програми; витрати на дорогу чи супровід не припускайте покритими.", "Auf der Seite „Hunger auf Kunst und Kultur“ das Bundesland wählen: Dort stehen Anspruch, Ausgabestellen und Partnerhäuser. Unterlagen und Gültigkeit prüfen; vor einer Veranstaltung klären, ob genau dieser Veranstalter teilnimmt und eine Reservierung nötig ist. Der Pass betrifft den Kultureintritt im Programm; Fahrt oder Begleitung nicht als gedeckt voraussetzen.", source: culturePass),
                .init("family-pass", "person.2", "Знижки для сімей", "Familienermäßigungen", "Умови сімейних карток і партнерів залежать від федеральної землі. Через державний огляд перейдіть до своєї землі, перевірте, хто може подати заяву, чи потрібна реєстрація та де діє знижка. Порівнюйте повну ціну поїздки: дорослі й дитячі квитки, дорога, прокат і платні додаткові програми. Не купуйте річний абонемент, доки не зіставите його з кількістю реальних відвідувань.", "Bedingungen für Familienpässe und Partner unterscheiden sich je Bundesland. Über die staatliche Übersicht das eigene Land öffnen und Anspruch, Antrag sowie gültige Vergünstigungen prüfen. Gesamtkosten des Ausflugs vergleichen: Erwachsenen- und Kindertickets, Anreise, Leihgebühren und Zusatzprogramme. Eine Jahreskarte erst mit der realistischen Zahl der Besuche abgleichen.", source: familyPass),
                .init("bathing", "water.waves", "Озеро або місце для купання", "See oder Badeplatz", "У базі AGES знайдіть офіційно контрольоване місце для купання та перевірте дату останнього вимірювання якості води. Не кожне невелике озеро входить до моніторингу. Окремо на сторінці оператора перевірте сезон, вхід, години, правила для дітей і собак та чи є нагляд рятувальників. Після сильних опадів або попередження про водорості враховуйте нові повідомлення на місці.", "In der AGES-Datenbank eine überwachte Badestelle suchen und das Datum der letzten Wasserqualitätsmessung prüfen. Nicht jeder kleine See wird erfasst. Auf der Seite des Betreibers Saison, Eintritt, Öffnungszeiten, Regeln für Kinder und Hunde sowie Badeaufsicht gesondert prüfen. Nach Starkregen oder Algenwarnungen aktuelle Hinweise vor Ort beachten.", source: bathing),
                .init("national-parks", "leaf", "Національні парки", "Nationalparks", "Офіційний огляд національних парків допомагає знайти центр відвідувачів, екскурсію або маршрут у потрібному регіоні. Перед поїздкою перевірте сезон, місце старту, тривалість, складність, мову екскурсії, вартість і бронювання. Самостійний маршрут і програма з гідом — різні пропозиції; не припускайте, що центр або екскурсія безплатні.", "Die offizielle Nationalparkübersicht hilft, Besucherzentrum, Führung oder Route in der gewünschten Region zu finden. Vorher Saison, Startpunkt, Dauer, Schwierigkeit, Sprache, Preis und Buchung prüfen. Ein eigener Rundweg und eine geführte Tour sind verschiedene Angebote; Zentrum oder Führung nicht als kostenlos voraussetzen.", source: parks),
                .init("park-rules", "signpost.right", "Правила в заповідних місцях", "Regeln im Schutzgebiet", "Перед прогулянкою в національному парку відкрийте правила саме цієї території. Зазвичай потрібно залишатися на визначених стежках, тримати собак на повідку; велосипед, купання, вогонь і ночівля можуть бути дозволені лише в окремих місцях або заборонені. Позначки на маршруті та вказівки адміністрації мають перевагу над старою картою чи дописом у соцмережі.", "Vor dem Besuch die Regeln des jeweiligen Nationalparks öffnen. Meist sind markierte Wege einzuhalten und Hunde anzuleinen; Radfahren, Baden, Feuer und Übernachten können nur an bestimmten Stellen erlaubt oder verboten sein. Beschilderung und Hinweise der Parkverwaltung sind verlässlicher als eine alte Karte oder ein Social-Media-Beitrag.", source: parkRules),
                .init("hiking", "figure.hiking", "Піший маршрут у горах", "Wanderung in den Bergen", "У рекомендаціях Альпійського клубу вибирайте маршрут за довжиною, перепадом висот, складністю й можливостями найповільнішого учасника. Перед виходом перевірте прогноз, стан стежки, спорядження та час повернення; залиште запас денного світла. Якщо плануєте з дітьми, коротший маршрут і можливість повернутися важливіші за заплановану вершину. Для правил парку звірте й місцеві вказівки.", "Nach Empfehlungen des Alpenvereins Tourlänge, Höhenmeter und Schwierigkeit an der langsamsten Person ausrichten. Vor dem Start Wetter, Wegzustand, Ausrüstung und Rückkehrzeit prüfen; Tageslichtreserve einplanen. Mit Kindern sind eine kürzere Tour und Umkehrmöglichkeit wichtiger als der geplante Gipfel. Für Schutzgebiete zusätzlich örtliche Regeln prüfen.", source: hiking)
            ],
            sources: [libraries, sport, museums, culturePass, familyPass, bathing, parks, parkRules, hiking]
        )
    }
}
